/**
 * Get an embedded skill by slug.
 */
export function getEmbeddedSkill(slug: string): EmbeddedSkill | null {
  return EMBEDDED_SKILLS.find((s) => s.slug === slug) ?? null;
}

/**
 * Get all embedded skills in a category.
 */
export function getEmbeddedSkillsByCategory(category: string): EmbeddedSkill[] {
  return EMBEDDED_SKILLS.filter((s) => s.category === category);
}

/**
 * Count embedded skills.
 */
export function countEmbeddedSkills(): number {
  return EMBEDDED_SKILLS.length;
}